mapper.select:
select t.id, g.cost_id, g.report_date, g.account_date, g.report_status, g.big_table_status, h.reconciliation_status, g.big_table_status, j.outstock_code, h.transport_no, h.track_no, h.confirm_time, j.shop_name, j.to_country, g.sku_no, g.delivery_qty, t.fee_type, t.bill_amount, t.fee_allocation_type, t.allocated_amount, t.product_allocated_amount, t.weight_allocation_type, t.org_name from small_bag_cost_allocation t left join small_bag_cost_allocation_detail g on t.main_id = g.id and g.is_deleted = false left join logistics_bill_cost h on g.cost_id = h.id and h.is_deleted = false left join logistics_bill j on h.logistics_bill_id = j.id and j.is_deleted = false
${params.sqlMap.default} and t.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.id desc
